<script>
(()=>{const el=document.getElementById('orderStatus'),actions=document.getElementById('orderActions');if(!el||!actions)return;async function check(){try{const r=await fetch(@json(route('orders.status',$order)),{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();el.textContent=d.status==='pending'&&d.approved?'Approved':d.status[0].toUpperCase()+d.status.slice(1);el.className='badge '+(d.status==='completed'?'bg-success':d.approved?'bg-info text-dark':'bg-warning text-dark');if(d.approved)document.getElementById('approvalBy').textContent=`Approved by ${d.approver??'Admin'} on ${d.approved_at??''}`;if(d.status==='pending'&&d.approved&&!actions.querySelector('form[action*="/complete"]')){const form=document.createElement('form');form.method='POST';form.action=actions.dataset.completeUrl;const token=document.createElement('input');token.type='hidden';token.name='_token';token.value=actions.dataset.csrf;const button=document.createElement('button');button.type='submit';button.className='btn btn-primary';button.textContent=actions.dataset.completeLabel;form.append(token,button);actions.prepend(form);}if(d.status==='completed'){actions.replaceChildren();}}catch(e){}}setInterval(check,5000)})();
</script>
